import './style.css'
import './mobile.css'

const KEY='seok-sdr-rules-v2', now=new Date(), currentMonth=now.toISOString().slice(0,7)
const defaults={settings:{name:'',startDate:'',salary:1500,goal:20,tax:12,bonusStep:25000,bonusValue:1000,guarantee:500,bands:[[6,1,12,2],[8,1.5,16,3],[10,2,20,4],[12,2.5,24,5]]},launches:[],contracts:[],team:[],tasks:[]}
let db=JSON.parse(localStorage.getItem(KEY)||'null')||structuredClone(defaults),tab='overview',edit={}
const $=s=>document.querySelector(s), uid=()=>crypto.randomUUID(), save=()=>localStorage.setItem(KEY,JSON.stringify(db))
const brl=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}), percent=n=>Number(n||0).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%'
const esc=s=>String(s||'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))
const dateBR=d=>d?new Date(d+'T12:00').toLocaleDateString('pt-BR'):'—', monthName=m=>new Date(m+'-02T12:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})
const val=(id,v)=>v==='recurringPayments'?'':edit[id]?.[v]??''
function monthInput(id='period'){return `<input id="${id}" class="month" type="month" value="${currentMonth}">`}
function inMonth(items,m,field='date'){return items.filter(x=>x[field]?.slice(0,7)===m)}
function validMeeting(x){return x.attended==='Sim'&&x.validated==='Sim'&&x.noShow!=='Sim'}
function tiers(meetings,origin){let k=meetings<=15?0:meetings<=19?1:meetings<=24?2:3,b=db.settings.bands||defaults.settings.bands;let pair=origin==='Outbound'?[b[k][2],b[k][3]]:[b[k][0],b[k][1]];return{initial:pair[0],recurring:pair[1],label:['Até 15 reuniões','16–19 reuniões','20–24 reuniões','25+ reuniões'][k]}}
function monthlyMetrics(m){let l=inMonth(db.launches,m), c=inMonth(db.contracts,m,'signedDate'), paid=db.contracts.filter(x=>x.firstPaid==='Sim'&&x.firstPaymentDate?.slice(0,7)===m);let ag=l.filter(x=>x.scheduled==='Sim').length,meet=l.filter(validMeeting).length,nos=l.filter(x=>x.noShow==='Sim').length,tries=l.reduce((n,x)=>n+ +x.attempts,0),answers=l.reduce((n,x)=>n+ +x.responses,0),contracts=c.filter(x=>x.status==='Assinado'||x.status==='Pago').length,newContracts=c.filter(x=>x.type==='Contrato novo'&&(x.status==='Assinado'||x.status==='Pago'));let gross=newContracts.reduce((n,x)=>n+ +x.gross,0),net=gross*(1- +db.settings.tax/100);return{l,c,paid,ag,meet,nos,tries,answers,contracts,newContracts,gross,net}}
function contractCalc(c){let m=c.signedDate?.slice(0,7)||currentMonth,meet=c.meetingsAtSigning??monthlyMetrics(m).meet,eligible=c.type==='Contrato novo'&&c.status!=='Cancelado'&&c.status!=='Perdido',t=c.commissionTier||tiers(meet,c.origin),base=c.netBase??(+c.gross*(1- +db.settings.tax/100)),initial=base*(c.initialRate??t.initial)/100,rec=base*(c.recurringRate??t.recurring)/100;let why=!eligible?(c.type!=='Contrato novo'?'Upsell e renovação não geram comissão.':'Contrato cancelado ou perdido.'):c.firstPaid!=='Sim'?'Aguardando pagamento da primeira fatura.':'';return{meet,t,base,initial,rec,eligible,why}}
function plannedPaymentDate(date){if(!date)return' Aguardando pagamento do cliente';let d=new Date(date+'T12:00'),payment=new Date(d.getFullYear(),d.getMonth()+1,20);return payment.toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'})}
function receiptMonth(date){return plannedPaymentDate(date)}
function lockExistingContracts(){let changed=false;db.contracts.forEach(c=>{if(c.commissionTier)return;let meet=monthlyMetrics(c.signedDate?.slice(0,7)||currentMonth).meet,t=tiers(meet,c.origin),base=+c.gross*(1- +db.settings.tax/100);Object.assign(c,{meetingsAtSigning:meet,commissionTier:t,initialRate:t.initial,recurringRate:t.recurring,netBase:base,recurringPayments:(c.recurringPayments||[]).map(p=>({...p,id:p.id||uid()}))});changed=true});if(changed)save()}
function nextMonth(m){if(!m)return'';let d=new Date(m+'-01T12:00');d.setMonth(d.getMonth()+1);return d.toISOString().slice(0,7)}
function commissionForMonth(m){let initial=0,recurring=0,predicted=0;db.contracts.forEach(c=>{let x=contractCalc(c);if(!x.eligible)return;let firstM=nextMonth(c.firstPaymentDate?.slice(0,7));if(c.firstPaid==='Sim'&&firstM===m)initial+=x.initial;if(c.status==='Assinado'&&c.firstPaid!=='Sim'&&nextMonth(c.signedDate?.slice(0,7))===m)predicted+=x.initial;let payments=(c.recurringPayments||[]).filter(p=>nextMonth(p.date?.slice(0,7))===m);recurring+=payments.reduce(n=>n+x.rec,0)});return{initial,recurring,predicted}}
function collective(m){let total=inMonth(db.team,m,'month').reduce((n,x)=>n+ +x.gross,0)*3,steps=Math.floor(total/(+db.settings.bonusStep||25000));return{total,steps,bonus:steps* +db.settings.bonusValue,remaining:Math.max(0,(steps+1)* +db.settings.bonusStep-total)}}
function inGuarantee(m){if(!db.settings.startDate)return false;let a=new Date(db.settings.startDate+'T12:00'),b=new Date(m+'-01T12:00');return b>=new Date(a.getFullYear(),a.getMonth(),1)&&b<new Date(a.getFullYear(),a.getMonth()+2,1)}
function remuneration(m){let com=commissionForMonth(m),raw=com.initial+com.recurring,guaranteed=inGuarantee(m)?Math.max(raw,+db.settings.guarantee):raw,bonus=collective(m).bonus;return{...com,raw,applicable:guaranteed,guarantee:Math.max(0,guaranteed-raw),bonus,total:+db.settings.salary+guaranteed+bonus}}
function card(l,v,d,c='blue'){return`<article class="card ${c}"><span>${l}</span><b>${v}</b><small>${d}</small></article>`}
function progress(v){return`<div class="goalbar"><div><span>Meta mensal: 20 reuniões validadas</span><b>${v} / 20</b></div><i><em style="width:${Math.min(100,v/20*100)}%"></em></i><small>${percent(v/20*100)} de atingimento</small></div>`}
function filterBar(){return`<div class="filter"><label>Mês e ano ${monthInput()}</label></div>`}
function overviewLegacy(){return''}
function overviewData(m,x,co,r,b){return`<div class="cards">${card('Agendamentos',x.ag,'Lançamentos do período')}${card('Reuniões validadas',x.meet,'Meta fixa: 20 reuniões','green')}${card('No-shows',x.nos,`${percent(x.ag?x.nos/x.ag*100:0)} dos agendamentos`,'orange')}${card('Pendências abertas',db.tasks.filter(t=>t.status!=='Concluída').length,'Todas as datas','purple')}</div><section class="panel meta">${progress(x.meet)}<div class="stats five"><div><span>Tentativas</span><b>${x.tries}</b></div><div><span>Respostas</span><b>${x.answers}</b></div><div><span>Taxa de resposta</span><b>${percent(x.tries?x.answers/x.tries*100:0)}</b></div><div><span>Contratos assinados</span><b>${x.contracts}</b></div><div><span>Contratos pagos</span><b>${x.paid.length}</b></div></div></section><div class="grid"><section class="panel"><header><div><h2>Contratos e comissão</h2><p>Somente regras comissionáveis</p></div></header><div class="metric-lines"><div><span>Valor mensal bruto (novos contratos)</span><b>${brl(x.gross)}</b></div><div><span>Valor líquido (−${db.settings.tax}% impostos)</span><b>${brl(x.net)}</b></div><div><span>Comissão inicial confirmada</span><b>${brl(co.initial)}</b></div><div><span>Comissão recorrente confirmada</span><b>${brl(co.recurring)}</b></div><div><span>Comissão prevista</span><b>${brl(co.predicted)}</b></div></div></section><section class="panel"><header><div><h2>Remuneração estimada</h2><p>Recebimento ocorre no mês seguinte ao pagamento</p></div></header><div class="metric-lines"><div><span>Salário fixo</span><b>${brl(db.settings.salary)}</b></div><div><span>Garantia de comissão</span><b>${r.guarantee?brl(r.guarantee):inGuarantee(m)?'Sem complemento':'Fora do período'}</b></div><div><span>Bônus coletivo ${b.steps?'estimado':'—'}</span><b>${brl(b.bonus)}</b></div><div class="total"><span>Remuneração total estimada</span><b>${brl(r.total)}</b></div></div></section></div>${charts(m)}</div>`}
function chartMonths(m){let d=new Date(m+'-01T12:00');return Array.from({length:6},(_,i)=>{let x=new Date(d.getFullYear(),d.getMonth()-5+i,1);return x.toISOString().slice(0,7)})}
function bars(title,labels,sets){let max=Math.max(1,...sets.flatMap(s=>s.values));return`<section class="panel chart-panel"><header><div><h2>${title}</h2><p>Dados alimentados pelos lançamentos</p></div></header><div class="legend">${sets.map(s=>`<i class="${s.color}"></i>${s.name}`).join('')}</div><div class="bars">${labels.map((l,i)=>`<div>${sets.map(s=>`<em class="${s.color}" style="height:${Math.max(2,s.values[i]/max*100)}%" title="${s.name}: ${s.values[i]}"></em>`).join('')}<small>${l.slice(5)}</small></div>`).join('')}</div></section>`}
function charts(m){let ms=chartMonths(m),metrics=ms.map(monthlyMetrics),rates=metrics.map(x=>({response:x.tries?x.answers/x.tries*100:0,noShow:x.ag?x.nos/x.ag*100:0})),cur=monthlyMetrics(m),inbound=db.launches.filter(x=>x.origin==='Inbound'&&x.date.slice(0,7)===m),outbound=db.launches.filter(x=>x.origin==='Outbound'&&x.date.slice(0,7)===m);let funnel=[cur.tries,cur.answers,cur.ag,cur.meet,cur.paid.length];let compare=o=>{let paid=inMonth(db.contracts.filter(c=>c.origin===o&&c.status==='Pago'),m,'signedDate'),net=paid.filter(c=>c.type==='Contrato novo').reduce((n,c)=>n+contractCalc(c).base,0),com=paid.reduce((n,c)=>n+contractCalc(c).initial,0);return{meet:(o==='Inbound'?inbound:outbound).filter(validMeeting).length,paid:paid.length,net,com}};let a=compare('Inbound'),z=compare('Outbound'),rem=ms.map(remuneration);return`<div class="chart-grid">${bars('Evolução da operação',ms,[{name:'Agendamentos',values:metrics.map(x=>x.ag),color:'blue'},{name:'Reuniões validadas',values:metrics.map(x=>x.meet),color:'green'},{name:'No-shows',values:metrics.map(x=>x.nos),color:'orange'},{name:'Contratos pagos',values:metrics.map(x=>x.paid.length),color:'purple'}])}${bars('Taxas mensais',ms,[{name:'Resposta (%)',values:rates.map(x=>x.response),color:'blue'},{name:'No-show (%)',values:rates.map(x=>x.noShow),color:'orange'}])}</div><div class="chart-grid">${bars('Funil do período',['Tentativas','Respostas','Agendados','Validadas','Pagos'],[{name:'Quantidade',values:funnel,color:'blue'}])}${bars('Inbound × Outbound',['Reuniões','Pagos','Líquido','Comissão'],[{name:'Inbound',values:[a.meet,a.paid,a.net,a.com],color:'green'},{name:'Outbound',values:[z.meet,z.paid,z.net,z.com],color:'purple'}])}</div>${bars('Remuneração mês a mês',ms,[{name:'Salário',values:ms.map(()=>+db.settings.salary),color:'blue'},{name:'Inicial',values:rem.map(x=>x.initial),color:'green'},{name:'Recorrente',values:rem.map(x=>x.recurring),color:'orange'},{name:'Bônus',values:rem.map(x=>x.bonus),color:'purple'},{name:'Total',values:rem.map(x=>x.total),color:'white'}])}`}
function launches(){let rows=[...db.launches].sort((a,b)=>b.date.localeCompare(a.date));return`<div class="head"><div><p class="eyebrow">OPERAÇÃO DIÁRIA</p><h1>Lançamentos manuais</h1><p>Uma reunião só entra na meta se compareceu, tinha perfil e foi validada pelo closer.</p></div></div><div class="two"><section class="panel form"><h2>${edit.launch?'Editar lançamento':'Novo lançamento'}</h2><form id="launch-form"><input type="hidden" name="id" value="${val('launch','id')}"><label>Data<input required name="date" type="date" value="${val('launch','date')||now.toISOString().slice(0,10)}"></label><label>Lead ou empresa<input required name="lead" value="${esc(val('launch','lead'))}"></label><label>Origem<select required name="origin"><option ${val('launch','origin')==='Inbound'?'selected':''}>Inbound</option><option ${val('launch','origin')==='Outbound'?'selected':''}>Outbound</option></select></label><div class="form-grid"><label>Tentativas de contato<input required min="0" name="attempts" type="number" value="${val('launch','attempts')||0}"></label><label>Respostas recebidas<input required min="0" name="responses" type="number" value="${val('launch','responses')||0}"></label></div>${radio('scheduled','Agendamento criado',val('launch','scheduled'))}${radio('attended','Lead compareceu',val('launch','attended'))}${radio('validated','Reunião validada pelo closer',val('launch','validated'))}${radio('noShow','No-show',val('launch','noShow'))}<label>Observação<textarea name="note">${esc(val('launch','note'))}</textarea></label><button class="primary">${edit.launch?'Salvar alterações':'Salvar lançamento'}</button></form></section><section class="panel"><header><div><h2>Histórico</h2><p>Filtre e edite seus registros</p></div><div class="table-filters">${monthInput('launch-month')}<select id="launch-origin"><option value="">Todas origens</option><option>Inbound</option><option>Outbound</option></select><select id="launch-status"><option value="">Todos status</option><option value="valid">Validada</option><option value="no">No-show</option></select></div></header><div id="launch-table">${launchTable(rows)}</div></section></div>`}
function radio(n,l,v){return`<label class="inline">${l}<select name="${n}"><option ${v==='Não'?'selected':''}>Não</option><option ${v==='Sim'?'selected':''}>Sim</option></select></label>`}
function launchTable(rows){return`<div class="table"><table><thead><tr><th>Data</th><th>Lead</th><th>Origem</th><th>Status</th><th></th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${dateBR(x.date)}</td><td><b>${esc(x.lead)}</b><small>${x.attempts} tentativa(s) · ${x.responses} resposta(s)</small></td><td>${x.origin}</td><td><span class="badge ${validMeeting(x)?'ok':x.noShow==='Sim'?'alert':''}">${validMeeting(x)?'Validada':x.noShow==='Sim'?'No-show':'Em andamento'}</span></td><td><button class="edit" data-edit="launch" data-id="${x.id}">Editar</button><button class="del" data-kind="launches" data-id="${x.id}">×</button></td></tr>`).join(''):`<tr><td colspan="5">Nenhum lançamento encontrado.</td></tr>`}</tbody></table></div>`}
function contracts(){let rows=[...db.contracts].sort((a,b)=>b.signedDate.localeCompare(a.signedDate));return`<div class="head"><div><p class="eyebrow">RESULTADOS E PAGAMENTOS</p><h1>Contratos e comissões</h1><p>As faixas são travadas pela quantidade de reuniões validadas no mês da assinatura.</p></div></div><div class="two"><section class="panel form"><h2>${edit.contract?'Editar contrato':'Novo contrato'}</h2><form id="contract-form"><input type="hidden" name="id" value="${val('contract','id')}"><label>Empresa ou cliente<input required name="company" value="${esc(val('contract','company'))}"></label><label>Lead vinculado<input required name="lead" value="${esc(val('contract','lead'))}"></label><div class="form-grid"><label>Origem<select name="origin"><option ${val('contract','origin')==='Inbound'?'selected':''}>Inbound</option><option ${val('contract','origin')==='Outbound'?'selected':''}>Outbound</option></select></label><label>Data da assinatura<input required name="signedDate" type="date" value="${val('contract','signedDate')||now.toISOString().slice(0,10)}"></label></div><label>Tipo<select name="type"><option>Contrato novo</option><option ${val('contract','type')==='Upsell'?'selected':''}>Upsell</option><option ${val('contract','type')==='Renovação'?'selected':''}>Renovação</option></select></label><label>Valor mensal bruto do contrato<input required min="0" step=".01" name="gross" type="number" value="${val('contract','gross')||''}"></label>${radio('firstPaid','Primeira fatura paga',val('contract','firstPaid'))}<label>Data do pagamento da primeira fatura<input name="firstPaymentDate" type="date" value="${val('contract','firstPaymentDate')}"></label>${radio('active','Cliente ativo',val('contract','active'))}<label>Status<select name="status"><option>Em negociação</option><option ${val('contract','status')==='Assinado'?'selected':''}>Assinado</option><option ${val('contract','status')==='Pago'?'selected':''}>Pago</option><option ${val('contract','status')==='Cancelado'?'selected':''}>Cancelado</option><option ${val('contract','status')==='Perdido'?'selected':''}>Perdido</option></select></label><label>Mensalidades recorrentes pagas (quantidade)<input required min="0" name="recurringCount" type="number" value="${val('contract','recurringPayments')?.length||0}"></label><label>Data de referência das recorrências<input name="recurringDate" type="date" value="${val('contract','recurringDate')||''}"></label><small class="hint">A quantidade será registrada com esta data. Para outro mês, edite o contrato e informe a nova data.</small><label>Observação<textarea name="note">${esc(val('contract','note'))}</textarea></label><button class="primary">${edit.contract?'Salvar alterações':'Salvar contrato'}</button></form></section><section class="panel"><header><div><h2>Contratos registrados</h2><p>Valores confirmados exigem pagamento da primeira fatura.</p></div></header>${contractTable(rows)}</section></div>`}
function contractTable(rows){return`<div class="table contract-table"><table><thead><tr><th>Contrato</th><th>Faixa travada</th><th>Base líquida</th><th>Comissão</th><th></th></tr></thead><tbody>${rows.length?rows.map(c=>{let x=contractCalc(c),confirmed=c.firstPaid==='Sim'?x.initial+(c.recurringPayments||[]).length*x.rec:0;return`<tr><td><b>${esc(c.company)}</b><small>${c.origin} · ${c.type} · ${c.status}</small><small>${x.why||`Recebimento inicial: ${receiptMonth(c.firstPaymentDate)}`}</small></td><td>${x.meet} reuniões<br><small>${x.t.label} (${x.t.initial}% / ${x.t.recurring}%)</small></td><td>${brl(x.base)}</td><td><b>${brl(confirmed)}</b><small>Prevista: ${c.firstPaid==='Sim'?brl(0):brl(x.initial)}</small></td><td><button class="edit" data-edit="contract" data-id="${c.id}">Editar</button><button class="del" data-kind="contracts" data-id="${c.id}">×</button></td></tr>`}).join(''):`<tr><td colspan="5">Nenhum contrato registrado.</td></tr>`}</tbody></table></div>`}
function bonus(){let m=currentMonth,b=collective(m);return`<div class="head"><div><p class="eyebrow">RESULTADO DO TIME</p><h1>Bônus coletivo</h1><p>O cálculo reinicia automaticamente a cada mês.</p></div>${filterBar()}</div><div id="bonus-data">${bonusData(m,b)}</div>`}
function bonusData(m,b){let rows=inMonth(db.team,m,'month');return`<div class="cards compact">${card('Volume elegível',brl(b.total),'Valor mensal do time × 3','green')}${card('Faixas completas',b.steps,`${brl(db.settings.bonusStep)} por faixa`)}${card('Bônus da SDR',brl(b.bonus),`${brl(db.settings.bonusValue)} por faixa`,'orange')}${card('Próxima faixa',brl(b.remaining),'Volume que falta','purple')}</div><div class="two"><section class="panel form"><h2>Contrato novo fechado pelo time</h2><form id="team-form"><label>Mês de referência<input required name="month" type="month" value="${m}"></label><label>Valor mensal bruto do contrato<input required min="0" step=".01" name="gross" type="number"></label><label>Observação<textarea name="note"></textarea></label><button class="primary">Adicionar ao mês</button></form></section><section class="panel"><h2>Contratos do time em ${monthName(m)}</h2><div class="table"><table><thead><tr><th>Valor mensal</th><th>Volume elegível</th><th>Observação</th><th></th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${brl(x.gross)}</td><td>${brl(x.gross*3)}</td><td>${esc(x.note)}</td><td><button class="del" data-kind="team" data-id="${x.id}">×</button></td></tr>`).join(''):`<tr><td colspan="4">Nenhum contrato do time informado.</td></tr>`}</tbody></table></div></section></div>`}
const taskTypes=['Lead sem retorno','Reunião aguardando validação do closer','Contrato assinado aguardando primeira fatura','Fatura pendente','Contrato cancelado','Comissão aguardando pagamento','Conferência mensal entre CRM, faturamento, recebimentos e controles próprios']
function tasks(){let rows=[...db.tasks].sort((a,b)=>a.due.localeCompare(b.due));return`<div class="head"><div><p class="eyebrow">ACOMPANHAMENTO</p><h1>Pendências</h1><p>Apenas pendências ligadas ao fluxo da operação SDR.</p></div></div><div class="two"><section class="panel form"><h2>${edit.task?'Editar pendência':'Nova pendência'}</h2><form id="task-form"><input type="hidden" name="id" value="${val('task','id')}"><label>Tipo<select required name="type">${taskTypes.map(x=>`<option ${val('task','type')===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Data prevista<input required name="due" type="date" value="${val('task','due')||now.toISOString().slice(0,10)}"></label><label>Status<select name="status">${['Aberta','Em andamento','Concluída','Atrasada'].map(x=>`<option ${val('task','status')===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Observação<textarea required name="note">${esc(val('task','note'))}</textarea></label><button class="primary">${edit.task?'Salvar alterações':'Adicionar pendência'}</button></form></section><section class="panel"><header><div><h2>Pendências cadastradas</h2><p>Status, previsão e acompanhamento</p></div></header><div class="table"><table><thead><tr><th>Tipo</th><th>Data prevista</th><th>Status</th><th></th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td><b>${esc(x.type)}</b><small>${esc(x.note)}</small></td><td>${dateBR(x.due)}</td><td><span class="badge ${x.status==='Concluída'?'ok':x.status==='Atrasada'?'alert':''}">${x.status}</span></td><td><button class="edit" data-edit="task" data-id="${x.id}">Editar</button><button class="del" data-kind="tasks" data-id="${x.id}">×</button></td></tr>`).join(''):`<tr><td colspan="4">Nenhuma pendência cadastrada.</td></tr>`}</tbody></table></div></section></div>`}
function settingsLegacy(){return`<div></div>`}
function settings(){let bands=db.settings.bands||defaults.settings.bands,labels=['Até 15','16–19','20–24','25+'];return`<div class="head"><div><p class="eyebrow">REGRAS DA OPERAÇÃO</p><h1>Configurações</h1><p>Parâmetros da SEOK e backup dos seus dados locais.</p></div></div><div class="two"><section class="panel form"><h2>Perfil e parâmetros</h2><form id="settings-form"><label>Nome da SDR<input required name="name" value="${esc(db.settings.name)}"></label><label>Data de início do contrato<input name="startDate" type="date" value="${db.settings.startDate}"></label><div class="form-grid"><label>Salário fixo (R$)<input required min="0" name="salary" type="number" value="${db.settings.salary}"></label><label>Meta de reuniões<input name="goal" type="number" value="20" readonly></label></div><div class="form-grid"><label>Impostos (%)<input required min="0" name="tax" type="number" value="${db.settings.tax}"></label><label>Garantia (R$)<input required min="0" name="guarantee" type="number" value="${db.settings.guarantee}"></label></div><div class="form-grid"><label>Faixa bônus (R$)<input required min="0" name="bonusStep" type="number" value="${db.settings.bonusStep}"></label><label>Bônus por faixa (R$)<input required min="0" name="bonusValue" type="number" value="${db.settings.bonusValue}"></label></div><h3>Faixas de comissão (%)</h3><div class="bands">${bands.map((b,i)=>`<fieldset><legend>${labels[i]} reuniões</legend><label>Inbound inicial<input required min="0" step=".1" name="i${i}" type="number" value="${b[0]}"></label><label>Inbound recorrente<input required min="0" step=".1" name="r${i}" type="number" value="${b[1]}"></label><label>Outbound inicial<input required min="0" step=".1" name="o${i}" type="number" value="${b[2]}"></label><label>Outbound recorrente<input required min="0" step=".1" name="or${i}" type="number" value="${b[3]}"></label></fieldset>`).join('')}</div><button class="primary">Salvar configurações</button></form></section><section class="panel rules"><h2>Regras aplicadas</h2><p>Base líquida = valor mensal bruto − ${db.settings.tax}% de impostos. A faixa é congelada ao assinar o contrato e o pagamento é projetado para o mês seguinte à fatura.</p><p>Comissão: apenas contratos novos, de lead da SDR, após pagamento da primeira fatura. Upsells, renovações e cancelamentos antes do primeiro pagamento não geram comissão.</p><hr><h2>Backup</h2><p>Todos os dados permanecem neste navegador.</p><div class="backup-actions"><button data-export="csv">↓ Exportar CSV</button><button data-export="json">↓ Exportar JSON</button><label>↑ Importar JSON<input id="import" type="file" accept=".json"></label></div></section></div>`}
function payoutRecords(m){let previous=prevMonth(m), guaranteed=[],confirming=[];db.contracts.forEach(c=>{let x=contractCalc(c),firstReceipt=nextMonth(c.firstPaymentDate?.slice(0,7));if(!x.eligible){if(c.status==='Cancelado'||c.status==='Perdido')confirming.push({c,x,state:'Cancelada',initial:0,recurring:0});else confirming.push({c,x,state:'Não comissionável',initial:0,recurring:0});return}if(c.firstPaid==='Sim'&&firstReceipt===m)guaranteed.push({c,x,state:'Garantida',initial:x.initial,recurring:0});if(c.status==='Assinado'&&c.firstPaid!=='Sim')confirming.push({c,x,state:'Aguardando pagamento',initial:x.initial,recurring:0});let paidRecurring=(c.recurringPayments||[]).some(p=>p.date?.slice(0,7)===previous);if(c.active==='Sim'&&c.firstPaid==='Sim'){if(paidRecurring)guaranteed.push({c,x,state:'Garantida',initial:0,recurring:x.rec});else confirming.push({c,x,state:'Recorrência esperada',initial:0,recurring:x.rec})}});return{guaranteed,confirming}}
function prevMonth(m){let d=new Date(m+'-01T12:00');d.setMonth(d.getMonth()-1);return d.toISOString().slice(0,7)}
function projectionTotals(m){let rec=payoutRecords(m),r=remuneration(m),guaranteed=rec.guaranteed.reduce((n,x)=>n+x.initial+x.recurring,0),potential=rec.confirming.reduce((n,x)=>n+x.initial+x.recurring,0),b=collective(m),bonusGuaranteed=m<currentMonth?b.bonus:0,bonusPotential=m<currentMonth?0:b.bonus;let commissionGuaranteed=Math.max(guaranteed,inGuarantee(m)?+db.settings.guarantee:0);return{...rec,commissionGuaranteed,guarantee:Math.max(0,commissionGuaranteed-guaranteed),guaranteedTotal:+db.settings.salary+commissionGuaranteed+bonusGuaranteed,potential,potentialBonus:bonusPotential,projected:+db.settings.salary+commissionGuaranteed+bonusGuaranteed+potential+bonusPotential,bonusGuaranteed,bonusPotential,active:rec.guaranteed.filter(x=>x.recurring).length+rec.confirming.filter(x=>x.recurring).length,activeRecurring:rec.guaranteed.filter(x=>x.recurring).reduce((n,x)=>n+x.recurring,0)+rec.confirming.filter(x=>x.recurring).reduce((n,x)=>n+x.recurring,0)}}
function priorityActions(){let overdue=db.tasks.filter(x=>x.status!=='Concluída'&&x.due<now.toISOString().slice(0,10)).length,awaitCloser=db.launches.filter(x=>x.attended==='Sim'&&x.validated!=='Sim'&&x.noShow!=='Sim').length,awaitInvoice=db.contracts.filter(x=>x.status==='Assinado'&&x.firstPaid!=='Sim').length,recurring=db.contracts.filter(x=>x.active==='Sim'&&x.firstPaid==='Sim'&&!(x.recurringPayments||[]).some(p=>p.date?.slice(0,7)===prevMonth(currentMonth))).length;return[['Reuniões aguardando validação',awaitCloser,'launches'],['Contratos aguardando primeira fatura',awaitInvoice,'contracts'],['Clientes com recorrência pendente',recurring,'projection'],['Pendências vencidas',overdue,'tasks']].filter(x=>x[1])}
function overview(){let m=currentMonth,x=monthlyMetrics(m),next=nextMonth(m),p=projectionTotals(next),name=esc(db.settings.name.trim());let title=name?`<h1 class="overview-title"><span>Visão geral</span><span>Seja bem-vindo novamente, ${name}</span></h1>`:'<h1>Visão geral</h1>';return`<div class="head dashboard-head"><div><p class="eyebrow">OPERAÇÃO SDR</p>${title}</div>${filterBar()}</div><div id="overview-data">${overviewNew(m,x,next,p)}</div>`}
function overviewLite(m,x,next,p,actions){return`<div class="cards decision-cards">${card('Reuniões validadas',`${x.meet} / 20`,'Meta mensal','green')}${card('Agendamentos',x.ag,'No período')}${card('No-shows',x.nos,'Acompanhe a qualidade','orange')}${card('Taxa de resposta',percent(x.tries?x.answers/x.tries*100:0),'Respostas / tentativas')}${card('Contratos pagos',x.paid.length,'Pagamento confirmado','green')}${card('Garantido no próximo pagamento',brl(p.guaranteedTotal),monthName(next))}${card('Total projetado',brl(p.projected),'Inclui confirmações','purple')}${card('Pendências que bloqueiam comissão',actions.reduce((n,x)=>n+x[1],0),'Exigem ação','orange')}</div><section class="panel actions"><header><div><h2>Ações prioritárias de hoje</h2><p>Itens que podem travar resultado ou recebimento.</p></div></header>${actions.length?`<div class="action-list">${actions.map(x=>`<button data-tab="${x[2]}"><span>${x[1]}</span><div><b>${x[0]}</b><small>Ver registros e agir agora</small></div><i>→</i></button>`).join('')}</div>`:`<div class="clear-state">Nenhuma ação crítica identificada hoje.</div>`}</section>`}
function projection(){let m=nextMonth(currentMonth),p=projectionTotals(m);return`<div class="head"><div><p class="eyebrow">PAGAMENTO ESTIMADO</p><h1>Projeção de recebimento</h1><p>Recebimentos estimados para ${monthName(m)}.</p></div><div class="filter"><label>Mês de pagamento <input id="period" class="month" type="month" value="${m}"></label></div></div><div id="projection-data">${projectionData(m,p)}</div>`}
function projectionData(m,p){let prev=prevMonth(m),previous=projectionTotals(prev),delta=p.guaranteedTotal-previous.guaranteedTotal,deltaPct=previous.guaranteedTotal?delta/previous.guaranteedTotal*100:0;return`<div class="projection-hero"><div><span>Total garantido a receber</span><b>${brl(p.guaranteedTotal)}</b><small>Salário + pagamentos já confirmados</small></div><div class="potential"><span>Em confirmação</span><b>${brl(p.potential+p.potentialBonus)}</b><small>Depende de faturas e volume final</small></div><div class="projected"><span>Projeção total</span><b>${brl(p.projected)}</b><small>Se todas as pendências forem pagas, você receberá ${brl(p.projected)}.</small></div></div><div class="projection-grid"><section class="panel"><header><div><h2>Garantido</h2><p>Valores já confirmados para ${monthName(m)}</p></div></header>${projectionLines([{l:'Salário fixo',v:db.settings.salary},{l:'Comissão inicial confirmada',v:p.guaranteed.reduce((n,x)=>n+x.initial,0)},{l:'Comissão recorrente confirmada',v:p.guaranteed.reduce((n,x)=>n+x.recurring,0)},{l:'Garantia mínima de comissão',v:p.guarantee},{l:'Bônus coletivo confirmado',v:p.bonusGuaranteed}],p.guaranteedTotal)}</section><section class="panel confirm"><header><div><h2>Em confirmação</h2><p>Não misturado ao valor garantido</p></div></header>${projectionLines([{l:'Contratos aguardando primeira fatura',v:p.confirming.reduce((n,x)=>n+x.initial,0)},{l:'Recorrências esperadas',v:p.confirming.reduce((n,x)=>n+x.recurring,0)},{l:'Bônus coletivo dependente do time',v:p.bonusPotential}],p.potential+p.potentialBonus)}</section></div><section class="panel"><header><div><h2>Comparativo mensal</h2><p>${monthName(prev)} → ${monthName(m)}</p></div><b class="variation ${delta>=0?'positive':'negative'}">${delta>=0?'+':'−'}${brl(Math.abs(delta))} · ${delta>=0?'+':''}${percent(deltaPct)}</b></header>${comparisonTable(previous,p)}<div class="stacked">${stackedBars(chartMonths(m))}</div></section><section class="panel"><header><div><h2>Contratos na projeção</h2><p>Mês estimado de recebimento: ${monthName(m)}.</p></div></header>${projectionTable([...p.guaranteed,...p.confirming],m)}</section>`}
function projectionLines(rows,total){return`<div class="metric-lines">${rows.map(x=>`<div><span>${x.l}</span><b>${brl(x.v)}</b></div>`).join('')}<div class="total"><span>Total</span><b>${brl(total)}</b></div></div>`}
function comparisonTable(a,b){let rows=[['Salário fixo',db.settings.salary,db.settings.salary],['Comissão inicial',a.guaranteed.reduce((n,x)=>n+x.initial,0),b.guaranteed.reduce((n,x)=>n+x.initial,0)],['Comissão recorrente',a.guaranteed.reduce((n,x)=>n+x.recurring,0),b.guaranteed.reduce((n,x)=>n+x.recurring,0)],['Bônus coletivo',a.bonusGuaranteed,b.bonusGuaranteed],['Total garantido',a.guaranteedTotal,b.guaranteedTotal],['Total projetado',a.projected,b.projected]];let previousSales=inMonth(db.contracts,prevMonth(currentMonth),'signedDate').filter(x=>x.type==='Contrato novo').length,currentSales=inMonth(db.contracts,currentMonth,'signedDate').filter(x=>x.type==='Contrato novo').length,previousCanceled=inMonth(db.contracts,prevMonth(currentMonth),'signedDate').filter(x=>x.status==='Cancelado').length,currentCanceled=inMonth(db.contracts,currentMonth,'signedDate').filter(x=>x.status==='Cancelado').length;return`<div class="table"><table><thead><tr><th>Componente</th><th>Mês anterior</th><th>Mês atual</th><th>Variação</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x[0]}</td><td>${brl(x[1])}</td><td>${brl(x[2])}</td><td class="${x[2]-x[1]>=0?'positive':'negative'}">${x[2]-x[1]>=0?'+':'−'}${brl(Math.abs(x[2]-x[1]))}</td></tr>`).join('')}<tr><td>Clientes ativos em recorrência</td><td>${a.active}</td><td>${b.active}</td><td>${b.active-a.active>=0?'+':''}${b.active-a.active}</td></tr><tr><td>Comissão recorrente ativa</td><td>${brl(a.activeRecurring)}</td><td>${brl(b.activeRecurring)}</td><td>${brl(b.activeRecurring-a.activeRecurring)}</td></tr><tr><td>Novas vendas na carteira</td><td>${previousSales}</td><td>${currentSales}</td><td>${currentSales-previousSales>=0?'+':''}${currentSales-previousSales}</td></tr><tr><td>Clientes cancelados</td><td>${previousCanceled}</td><td>${currentCanceled}</td><td>${currentCanceled-previousCanceled>=0?'+':''}${currentCanceled-previousCanceled}</td></tr></tbody></table></div>`}
function stackedBars(ms){let all=ms.map(m=>{let p=projectionTotals(m);return{m,s:+db.settings.salary,i:p.guaranteed.reduce((n,x)=>n+x.initial,0),r:p.guaranteed.reduce((n,x)=>n+x.recurring,0),b:p.bonusGuaranteed}}),max=Math.max(1,...all.map(x=>x.s+x.i+x.r+x.b));return`<div class="stack-legend"><i class="blue"></i>Salário <i class="green"></i>Inicial <i class="orange"></i>Recorrente <i class="purple"></i>Bônus</div><div class="stack-bars">${all.map(x=>`<div><span style="height:${x.s/max*100}%" class="blue"></span><span style="height:${x.i/max*100}%" class="green"></span><span style="height:${x.r/max*100}%" class="orange"></span><span style="height:${x.b/max*100}%" class="purple"></span><small>${x.m.slice(5)}</small></div>`).join('')}</div>`}
function projectionTable(rows,m){return`<div class="table"><table><thead><tr><th>Cliente</th><th>Origem</th><th>Bruto / líquido</th><th>Faixa</th><th>Inicial / recorrente</th><th>Status</th><th>Recebimento</th></tr></thead><tbody>${rows.length?rows.map(z=>`<tr><td><b>${esc(z.c.company)}</b></td><td>${z.c.origin}</td><td>${brl(z.c.gross)}<small>${brl(z.x.base)}</small></td><td>${z.x.t.label}<small>${z.x.t.initial}% / ${z.x.t.recurring}%</small></td><td>${brl(z.x.initial)}<small>${brl(z.x.rec)}</small></td><td><span class="badge ${z.state==='Garantida'?'ok':z.state==='Cancelada'||z.state==='Não comissionável'?'alert':''}">${z.state}</span></td><td>${monthName(m)}</td></tr>`).join(''):`<tr><td colspan="7">Nenhum contrato impacta este recebimento.</td></tr>`}</tbody></table></div>`}
function overviewNew(m,x,next,p){let days=Math.max(0,new Date(+m.slice(0,4),+m.slice(5),0).getDate()-new Date().getDate()),missing=Math.max(0,20-x.meet),rate=days?missing/days:missing;let r=remuneration(next),co=commissionForMonth(next),b=collective(next),noShow=x.ag?x.nos/x.ag*100:0,answer=x.tries?x.answers/x.tries*100:0,conversion=x.meet?x.paid.length/x.meet*100:0;return`<div class="status-strip"><span>Mês selecionado <b>${monthName(m)}</b></span><span>Próximo recebimento <b>${monthName(next)}</b></span><span>Atualizado agora</span></div><section class="top-financial"><article class="panel focus-card"><p class="eyebrow">META DE REUNIÕES</p><b class="hero-number">${x.meet}<small>/ 20</small></b><div class="goalbar"><i><em style="width:${Math.min(100,x.meet/20*100)}%"></em></i></div><div class="focus-lines"><span>${percent(x.meet/20*100)} atingido</span><span>${missing} faltam · ${rate.toLocaleString('pt-BR',{maximumFractionDigits:1})}/dia</span></div></article><article class="panel focus-card"><p class="eyebrow">PRÓXIMO PAGAMENTO GARANTIDO</p>${financialList([{l:'Salário fixo',v:db.settings.salary},{l:'Comissão inicial confirmada',v:co.initial},{l:'Comissão recorrente confirmada',v:co.recurring},{l:'Bônus coletivo confirmado',v:p.bonusGuaranteed},{l:'Garantia mínima',v:p.guarantee}])}<b class="focus-total">${brl(p.guaranteedTotal)}</b></article><article class="panel focus-card"><p class="eyebrow">PRÓXIMO PAGAMENTO PROJETADO</p>${financialList([{l:'Total garantido',v:p.guaranteedTotal},{l:'Contratos aguardando pagamento',v:p.confirming.reduce((n,z)=>n+z.initial,0)},{l:'Recorrências previstas',v:p.confirming.reduce((n,z)=>n+z.recurring,0)},{l:'Bônus coletivo potencial',v:p.bonusPotential}])}<b class="focus-total projected-text">${brl(p.projected)}</b><small>Se os pagamentos pendentes forem confirmados, você receberá ${brl(p.projected)}.</small></article></section><section class="panel metric-section"><header><div><h2>Operação SDR</h2><p>Leitura diária da atividade e qualidade do funil.</p></div></header><div class="metric-grid">${mini('Tentativas de contato',x.tries)}${mini('Respostas',x.answers)}${mini('Taxa de resposta',percent(answer))}${mini('Agendamentos',x.ag)}${mini('Reuniões validadas',x.meet,'positive')}${mini('Meta de reuniões','20')}${mini('Atingimento',percent(x.meet/20*100),'positive')}${mini('No-shows',x.nos,'attention')}${mini('Taxa de no-show',percent(noShow),'attention')}${mini('Contratos assinados',x.contracts)}${mini('Contratos pagos',x.paid.length,'positive')}${mini('Conversão reunião → pago',percent(conversion))}${mini('Pendências abertas',db.tasks.filter(t=>t.status!=='Concluída').length,'attention')}</div></section><section class="panel metric-section"><header><div><h2>Receita e comissão</h2><p>Confirmado e previsto permanecem visualmente separados.</p></div></header><div class="metric-grid financial-grid">${mini('Valor mensal bruto',brl(x.gross))}${mini('Base líquida',brl(x.net))}${mini('Comissão inicial confirmada',brl(co.initial),'positive')}${mini('Comissão inicial prevista',brl(co.predicted),'blue-text')}${mini('Comissão recorrente confirmada',brl(co.recurring),'positive')}${mini('Comissão recorrente prevista',brl(p.confirming.reduce((n,z)=>n+z.recurring,0)),'blue-text')}${mini('Bônus confirmado',brl(p.bonusGuaranteed),'positive')}${mini('Bônus potencial',brl(p.bonusPotential),'blue-text')}${mini('Salário fixo',brl(db.settings.salary))}${mini('Garantia de comissão',brl(p.guarantee))}${mini('Total garantido',brl(p.guaranteedTotal),'positive')}${mini('Total projetado',brl(p.projected),'blue-text')}</div></section><section class="panel actions"><header><div><h2>Ações prioritárias de hoje</h2><p>Itens que podem bloquear resultado ou comissão.</p></div></header>${priorityActions().length?`<div class="action-list">${priorityActions().map(z=>`<button data-tab="${z[2]}"><span>${z[1]}</span><div><b>${z[0]}</b><small>Abrir registros</small></div><i>→</i></button>`).join('')}</div>`:`<div class="clear-state">Nenhuma ação crítica identificada.</div>`}</section>${dashboardCharts(m,x,next)}`}
function financialList(rows){return`<div class="compact-lines">${rows.map(x=>`<div><span>${x.l}</span><b>${brl(x.v)}</b></div>`).join('')}</div>`}
function mini(l,v,c=''){return`<div class="mini-metric ${c}"><span>${l}</span><b>${v}</b></div>`}
function dashboardCharts(m,x,next){let ms=chartMonths(m),vals=ms.map(monthlyMetrics),pay=ms.map(k=>projectionTotals(nextMonth(k)));let empty=db.launches.length===0&&db.contracts.length===0;return`<section class="chart-title"><h2>Indicadores e tendências</h2><p>Todos os gráficos usam registros manuais. ${empty?'Adicione lançamentos ou contratos para alimentá-los.':''}</p></section><div class="chart-grid comprehensive">${realBars('Evolução mensal da operação',ms,[['Agendamentos',vals.map(z=>z.ag),'blue'],['Reuniões validadas',vals.map(z=>z.meet),'green'],['No-shows',vals.map(z=>z.nos),'orange'],['Contratos pagos',vals.map(z=>z.paid.length),'red']])}${funnelChart(x)}${inboundChart(m)}${realBars('Evolução financeira mensal',ms,[['Salário',ms.map(()=>+db.settings.salary),'blue'],['Inicial',pay.map(z=>z.guaranteed.reduce((n,q)=>n+q.initial,0)),'green'],['Recorrente',pay.map(z=>z.guaranteed.reduce((n,q)=>n+q.recurring,0)),'orange'],['Bônus',pay.map(z=>z.bonusGuaranteed),'purple']])}${recurrenceChart(ms)}${meetingGoal(x,m)}</div>`}
function realBars(title,ms,sets){let max=Math.max(1,...sets.flatMap(z=>z[1]));return`<section class="panel data-chart"><header><div><h2>${title}</h2><p>Últimos 6 meses</p></div></header><div class="legend">${sets.map(z=>`<i class="${z[2]}"></i>${z[0]}`).join('')}</div><div class="bars">${ms.map((k,i)=>`<div>${sets.map(z=>`<em class="${z[2]}" style="height:${Math.max(2,z[1][i]/max*100)}%"></em>`).join('')}<small>${k.slice(5)}</small></div>`).join('')}</div></section>`}
function funnelChart(x){let items=[['Tentativas',x.tries],['Respostas',x.answers],['Agendamentos',x.ag],['Reuniões validadas',x.meet],['Contratos pagos',x.paid.length]],max=Math.max(1,x.tries);return`<section class="panel data-chart"><header><div><h2>Funil de SDR</h2><p>Quantidade e conversão por etapa</p></div></header><div class="funnel">${items.map((z,i)=>`<div style="width:${Math.max(20,z[1]/max*100)}%"><b>${z[1]}</b><span>${z[0]}</span><small>${i?percent(items[i-1][1]?z[1]/items[i-1][1]*100:0):'Base'}</small></div>`).join('')}</div></section>`}
function inboundChart(m){let calc=o=>{let l=inMonth(db.launches.filter(x=>x.origin===o),m),c=db.contracts.filter(x=>x.origin===o&&x.firstPaid==='Sim'&&x.firstPaymentDate?.slice(0,7)===m);return[l.filter(validMeeting).length,c.length,c.filter(x=>x.type==='Contrato novo').reduce((n,x)=>n+contractCalc(x).base,0),c.reduce((n,x)=>n+contractCalc(x).initial,0)]},a=calc('Inbound'),b=calc('Outbound');return`<section class="panel data-chart"><header><div><h2>Inbound × Outbound</h2><p>Reuniões, pagos, valor líquido e comissão</p></div></header><div class="compare-bars">${['Reuniões validadas','Contratos pagos','Valor líquido','Comissão gerada'].map((l,i)=>`<div><span>${l}</span><i><em class="green" style="width:${Math.max(3,a[i]/Math.max(1,a[i],b[i])*100)}%"></em></i><b>In ${i>1?brl(a[i]):a[i]}</b><i><em class="blue" style="width:${Math.max(3,b[i]/Math.max(1,a[i],b[i])*100)}%"></em></i><b>Out ${i>1?brl(b[i]):b[i]}</b></div>`).join('')}</div></section>`}
function recurrenceChart(ms){let d=ms.map(k=>{let p=projectionTotals(nextMonth(k));return[p.active,p.guaranteed.filter(x=>x.recurring).reduce((n,x)=>n+x.recurring,0),p.confirming.filter(x=>x.recurring).reduce((n,x)=>n+x.recurring,0),inMonth(db.contracts,k,'signedDate').filter(x=>x.status==='Cancelado').length]});return realBars('Recorrência da carteira',ms,[['Clientes ativos',d.map(x=>x[0]),'blue'],['Recorrente confirmada',d.map(x=>x[1]),'green'],['Recorrente prevista',d.map(x=>x[2]),'purple'],['Cancelados',d.map(x=>x[3]),'red']])}
function meetingGoal(x,m){let last=new Date(+m.slice(0,4),+m.slice(5),0).getDate(),left=Math.max(0,last-new Date().getDate()),needed=Math.max(0,20-x.meet);return`<section class="panel data-chart"><header><div><h2>Meta de reuniões</h2><p>0 a 20 reuniões validadas</p></div></header><div class="meeting-progress"><b>${x.meet}<small> / 20</small></b><i><em style="width:${Math.min(100,x.meet/20*100)}%"></em></i><div><span>${left} dias restantes</span><span>${left?(needed/left).toLocaleString('pt-BR',{maximumFractionDigits:1}):needed} reuniões/dia necessárias</span></div></div></section>`}
function funnelVisual(x){let stages=[['Tentativas de contato',x.tries],['Respostas',x.answers],['Agendamentos',x.ag],['Reuniões validadas',x.meet],['Contratos assinados',x.contracts],['Contratos pagos',x.paid.length]],has=stages.some(z=>z[1]>0),max=Math.max(1,x.tries),w=960,h=150,step=w/stages.length,heights=stages.map(z=>has?Math.max(28,112*z[1]/max):42),pointsTop=heights.map((v,i)=>`${i*step},${(h-v)/2}`).join(' '),pointsBottom=heights.map((v,i)=>`${(i+1)*step},${(h+v)/2}`).reverse().join(' ');return`<section class="panel funnel-card"><header><div><h2>Funil da operação SDR</h2><p>Conversão real entre as etapas da sua operação.</p></div></header><div class="funnel-flow ${has?'':'is-empty'}"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="funnelGradient" x1="0" x2="1"><stop stop-color="#5C9DFF"/><stop offset="1" stop-color="#5361C9"/></linearGradient></defs><polygon points="${pointsTop} ${pointsBottom}" fill="url(#funnelGradient)" opacity="${has?'.78':'.16'}"/>${stages.slice(1).map((_,i)=>`<line x1="${(i+1)*step}" y1="25" x2="${(i+1)*step}" y2="125" stroke="#B5C0D4" stroke-opacity=".26"/>`).join('')}</svg><div class="funnel-columns">${stages.map((z,i)=>`<div><span>${z[0]}</span><b>${has?percent(z[1]/max*100):'—'}</b><small>${has?z[1]:' '}</small><em>${has&&i?percent(stages[i-1][1]?z[1]/stages[i-1][1]*100:0)+' da etapa anterior':''}</em></div>`).join('')}</div></div>${has?'':`<p class="empty-chart">Adicione lançamentos para visualizar sua conversão.</p>`}<div class="funnel-support"><span>Meta: <b>20 reuniões</b></span><span>Atingimento: <b>${percent(x.meet/20*100)}</b></span><span>No-shows: <b>${x.nos}</b></span><span>Taxa de no-show: <b>${percent(x.ag?x.nos/x.ag*100:0)}</b></span><span>Conversão validada → pago: <b>${percent(x.meet?x.paid.length/x.meet*100:0)}</b></span><span>Pendências abertas: <b>${db.tasks.filter(t=>t.status!=='Concluída').length}</b></span></div></section>`}
function lineVisual(title,months,series,emptyMessage,format=v=>v){let has=series.some(s=>s.values.some(v=>v>0));if(!has)return`<section class="panel data-chart line-card"><header><div><h2>${title}</h2><p>Últimos 6 meses</p></div></header><div class="line-empty"><span>⌁</span>${emptyMessage}</div></section>`;let max=Math.max(1,...series.flatMap(s=>s.values)),w=800,h=180,pad=20,coords=s=>s.values.map((v,i)=>`${pad+i*(w-pad*2)/(months.length-1)},${h-pad-v/max*(h-pad*2)}`).join(' ');return`<section class="panel data-chart line-card"><header><div><h2>${title}</h2><p>Últimos 6 meses</p></div></header><div class="legend">${series.map(s=>`<i class="${s.color}"></i>${s.name}`).join('')}</div><div class="line-wrap"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="20" y1="20" x2="780" y2="20" class="gridline"/><line x1="20" y1="90" x2="780" y2="90" class="gridline"/><line x1="20" y1="160" x2="780" y2="160" class="gridline"/>${series.map(s=>`<polyline points="${coords(s)}" fill="none" stroke="${s.hex}" stroke-width="2.5"/>${s.values.map((v,i)=>{let p=coords(s).split(' ')[i].split(',');return`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="${s.hex}"><title>${s.name}: ${format(v)}</title></circle>`}).join('')}`).join('')}</svg><div class="line-axis">${months.map(x=>`<span>${x.slice(5)}</span>`).join('')}</div></div></section>`}
function recurrenceVisual(months){let p=months.map(k=>projectionTotals(nextMonth(k))),confirmed=p.map(x=>x.guaranteed.filter(z=>z.recurring).reduce((n,z)=>n+z.recurring,0)),expected=p.map(x=>x.confirming.filter(z=>z.recurring).reduce((n,z)=>n+z.recurring,0)),active=p[p.length-1].active,canceled=inMonth(db.contracts,months[months.length-1],'signedDate').filter(x=>x.status==='Cancelado').length;return`<section class="panel data-chart recurrence-card"><header><div><h2>Recorrência da carteira</h2><p>Comissão recorrente em BRL</p></div></header><div class="recurrence-kpis"><span>Clientes ativos <b>${active}</b></span><span>Confirmada <b>${brl(confirmed.at(-1))}</b></span><span>Prevista <b>${brl(expected.at(-1))}</b></span><span>Cancelados <b>${canceled}</b></span></div>${lineVisual(' ',months,[{name:'Confirmada',values:confirmed,color:'green',hex:'#44D7A8'},{name:'Prevista',values:expected,color:'blue',hex:'#5C9DFF'}],'Registre pagamentos recorrentes para acompanhar sua carteira.',brl).replace(/<header>[\s\S]*?<\/header>/,'')}</section>`}
function dashboardChartsVisual(m,x,next){let months=chartMonths(m),vals=months.map(monthlyMetrics);return`<div class="visual-gap">${funnelVisual(x)}</div><div class="chart-grid chart-pair">${lineVisual('Evolução mensal da operação',months,[{name:'Agendamentos',values:vals.map(z=>z.ag),color:'blue',hex:'#5C9DFF'},{name:'Reuniões validadas',values:vals.map(z=>z.meet),color:'green',hex:'#44D7A8'},{name:'No-shows',values:vals.map(z=>z.nos),color:'orange',hex:'#F5B84B'},{name:'Contratos pagos',values:vals.map(z=>z.paid.length),color:'red',hex:'#FF7272'}],'Os gráficos aparecerão quando houver lançamentos neste período.')}${recurrenceVisual(months)}</div>${inboundChart(m)}${realBars('Evolução financeira mensal',months,[['Salário',months.map(()=>+db.settings.salary),'blue'],['Inicial',months.map(k=>projectionTotals(nextMonth(k)).guaranteed.reduce((n,q)=>n+q.initial,0)),'green'],['Recorrente',months.map(k=>projectionTotals(nextMonth(k)).guaranteed.reduce((n,q)=>n+q.recurring,0)),'orange'],['Bônus',months.map(k=>projectionTotals(nextMonth(k)).bonusGuaranteed),'purple']])}${meetingGoal(x,m)}`}
dashboardCharts=dashboardChartsVisual
function dailyMetrics(date){let launches=db.launches.filter(x=>x.date===date),contracts=db.contracts.filter(x=>x.signedDate===date),paid=db.contracts.filter(x=>x.firstPaymentDate===date&&x.firstPaid==='Sim');let ag=launches.filter(x=>x.scheduled==='Sim').length,meet=launches.filter(validMeeting).length,nos=launches.filter(x=>x.noShow==='Sim').length,tries=launches.reduce((n,x)=>n+ +x.attempts,0),answers=launches.reduce((n,x)=>n+ +x.responses,0);return{launches,contracts,paid,ag,meet,nos,tries,answers}}
function daily(){let date=now.toISOString().slice(0,10),d=dailyMetrics(date),m=date.slice(0,7),monthMetrics=monthlyMetrics(m),paymentMonth=nextMonth(m),payment=projectionTotals(paymentMonth);return`<div class="head daily-head"><div><p class="eyebrow">REUNIÃO DIÁRIA</p><h1>Daily de performance</h1><p>Resumo objetivo do dia e do andamento mensal.</p></div><div class="daily-actions"><input id="daily-date" class="month" type="date" value="${date}"><button id="presentation" class="secondary">Modo apresentação</button><button id="copy-daily" class="primary">Copiar resumo</button></div></div><div id="daily-data">${dailyData(date,d,monthMetrics,payment,paymentMonth)}</div>`}
function dailyData(date,d,m,p,paymentMonth){let last=new Date(+date.slice(0,4),+date.slice(5,7),0).getDate(),left=Math.max(0,last-new Date(date+'T12:00').getDate()),missing=Math.max(0,20-m.meet),pace=left?missing/left:missing,attention=priorityActions();return`<section class="panel daily-section"><header><div><h2>Resultado do dia</h2><p>${dateBR(date)}</p></div></header><div class="daily-kpis">${[['Tentativas',d.tries],['Respostas',d.answers],['Taxa de resposta',percent(d.tries?d.answers/d.tries*100:0)],['Agendamentos',d.ag],['Reuniões validadas',d.meet],['No-shows',d.nos],['Contratos assinados',d.contracts.length],['Contratos pagos',d.paid.length]].map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></section><div class="daily-funnel">${funnelVisual({tries:d.tries,answers:d.answers,ag:d.ag,meet:d.meet,contracts:d.contracts.length,paid:d.paid,nos:d.nos})}</div><section class="panel daily-section"><header><div><h2>Andamento do mês</h2><p>${monthName(date.slice(0,7))}</p></div></header><div class="daily-lines monthly-progress">${[['Reuniões validadas',`${m.meet} / 20`],['Atingimento',percent(m.meet/20*100)],['Restante',missing],['Dias restantes',left],['Ritmo necessário',`${pace.toLocaleString('pt-BR',{maximumFractionDigits:1})} por dia`],['Agendamentos acumulados',m.ag],['No-shows acumulados',m.nos],['Taxa de resposta acumulada',percent(m.tries?m.answers/m.tries*100:0)],['Contratos pagos acumulados',m.paid.length]].map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></section>${attention.length||d.nos?`<section class="panel daily-section attention-section"><header><div><h2>Pontos de atenção</h2><p>Aja nestes itens antes da próxima daily.</p></div></header><div class="attention-list">${attention.map(x=>`<span>${x[0]} <b>${x[1]}</b></span>`).join('')}${d.nos?`<span>No-shows do dia <b>${d.nos}</b></span>`:''}</div></section>`:''}`}
function dailySummary(date){let d=dailyMetrics(date),m=monthlyMetrics(date.slice(0,7)),missing=Math.max(0,20-m.meet),last=new Date(+date.slice(0,4),+date.slice(5,7),0).getDate(),left=Math.max(0,last-new Date(date+'T12:00').getDate()),pace=left?missing/left:missing,a=priorityActions();return`Daily SDR — ${dateBR(date)}\nHoje: ${d.tries} tentativas, ${d.answers} respostas (${percent(d.tries?d.answers/d.tries*100:0)}), ${d.ag} agendamentos, ${d.meet} reuniões validadas, ${d.nos} no-shows e ${d.paid.length} contratos pagos.\nMês: ${m.meet} de 20 reuniões validadas, faltam ${missing}, ritmo necessário de ${pace.toLocaleString('pt-BR',{maximumFractionDigits:1})} por dia.\nPontos de atenção: ${a.length?a.map(x=>`${x[0]} (${x[1]})`).join(', '):'nenhum item crítico.'}`}
function bindDaily(){let input=$('#daily-date');input?.addEventListener('change',e=>{let date=e.target.value,d=dailyMetrics(date),m=monthlyMetrics(date.slice(0,7)),pm=nextMonth(date.slice(0,7));$('#daily-data').innerHTML=dailyData(date,d,m,projectionTotals(pm),pm)});$('#presentation')?.addEventListener('click',()=>document.body.classList.toggle('presentation-mode'));$('#copy-daily')?.addEventListener('click',async()=>{let date=$('#daily-date')?.value||now.toISOString().slice(0,10),text=dailySummary(date);try{await navigator.clipboard.writeText(text);toast('Resumo copiado')}catch{let t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();toast('Resumo copiado')}})}
const pages={overview,launches,contracts,daily,projection,bonus,tasks,settings}
function render(){let initials=(db.settings.name||'SD').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();$('#app').innerHTML=`<aside><a class="brand"><b>seok</b><i>SDR</i></a><nav>${[['overview','⌂','Visão geral'],['daily','◉','Daily de performance'],['launches','✦','Lançamentos manuais'],['contracts','R$','Contratos e comissões'],['projection','◫','Projeção de recebimento'],['bonus','◎','Bônus coletivo'],['tasks','◷','Pendências'],['settings','⚙','Configurações']].map(x=>`<button class="${tab===x[0]?'active':''}" data-tab="${x[0]}"><span>${x[1]}</span>${x[2]}</button>`).join('')}</nav><footer><i>${initials}</i><p><b>${esc(db.settings.name||'SDR')}</b><small>SDR · SEOK</small></p></footer></aside><main><header class="mobile"><button id="menu">☰</button><a class="brand"><b>seok</b><i>SDR</i></a><button data-tab="settings">⚙</button></header><div class="content">${pages[tab]()}</div></main><div id="toast"></div>`;bind();bindDaily()}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;edit={};render()});$('#menu')?.addEventListener('click',()=>$('aside').classList.toggle('open'));$('#period')?.addEventListener('change',e=>tab==='overview'?refreshOverviewLite(e.target.value):tab==='projection'?refreshProjection(e.target.value):refreshBonus(e.target.value));$('#launch-month')?.addEventListener('change',filterLaunches);$('#launch-origin')?.addEventListener('change',filterLaunches);$('#launch-status')?.addEventListener('change',filterLaunches);$('#launch-form')?.addEventListener('submit',e=>storeLaunch(e));$('#contract-form')?.addEventListener('submit',e=>storeContract(e));$('#team-form')?.addEventListener('submit',e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));db.team.push({id:uid(),month:x.month,gross:+x.gross,note:x.note});save();render();toast('Contrato do time adicionado')});$('#task-form')?.addEventListener('submit',e=>storeGeneric(e,'tasks','task'));$('#settings-form')?.addEventListener('submit',saveSettings);document.querySelectorAll('.del').forEach(b=>b.onclick=()=>{db[b.dataset.kind]=db[b.dataset.kind].filter(x=>x.id!==b.dataset.id);save();render()});document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>{let kind=b.dataset.edit,map={launch:'launches',contract:'contracts',task:'tasks'};edit[kind]=structuredClone(db[map[kind]].find(x=>x.id===b.dataset.id));render()});$('[data-export="json"]')?.addEventListener('click',()=>download(JSON.stringify(db,null,2),'backup-seok-sdr.json','application/json'));$('[data-export="csv"]')?.addEventListener('click',exportCSV);$('#import')?.addEventListener('change',importJSON)}
function refreshOverview(m){let x=monthlyMetrics(m),co=commissionForMonth(m),r=remuneration(m),b=collective(m);$('#overview-data').innerHTML=overviewData(m,x,co,r,b)}
function refreshOverviewLite(m){let x=monthlyMetrics(m),next=nextMonth(m),p=projectionTotals(next);$('#overview-data').innerHTML=overviewNew(m,x,next,p);bind()}
function refreshProjection(m){$('#projection-data').innerHTML=projectionData(m,projectionTotals(m));bind()}
function refreshBonus(m){$('#bonus-data').innerHTML=bonusData(m,collective(m));bind()}
function saveSettings(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target)),bands=(db.settings.bands||defaults.settings.bands).map((_,i)=>[+x[`i${i}`],+x[`r${i}`],+x[`o${i}`],+x[`or${i}`]]);delete x.i0;delete x.r0;delete x.o0;delete x.or0;delete x.i1;delete x.r1;delete x.o1;delete x.or1;delete x.i2;delete x.r2;delete x.o2;delete x.or2;delete x.i3;delete x.r3;delete x.o3;delete x.or3;db.settings={...db.settings,...x,bands};save();render();toast('Configurações salvas')}
function filterLaunches(){let m=$('#launch-month').value,o=$('#launch-origin').value,s=$('#launch-status').value,rows=db.launches.filter(x=>(!m||x.date.startsWith(m))&&(!o||x.origin===o)&&(!s||(s==='valid'?validMeeting(x):x.noShow==='Sim')));$('#launch-table').innerHTML=launchTable(rows);bind()}
function storeLaunch(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));if(+x.responses>+x.attempts){alert('Respostas não podem superar tentativas.');return}if(x.noShow==='Sim'&&x.scheduled!=='Sim'){alert('No-show exige um agendamento criado.');return}if(x.noShow==='Sim')x.attended='Não';upsert('launches',x,'launch');toast('Lançamento salvo')}
function storeContract(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target)),old=edit.contract;if(x.firstPaid==='Sim'&&!x.firstPaymentDate){alert('Informe a data de pagamento da primeira fatura.');return}let count=+x.recurringCount||0;if(count&&(x.active!=='Sim'||x.firstPaid!=='Sim')){alert('Recorrências exigem cliente ativo e primeira fatura paga.');return}if(count&&!x.recurringDate){alert('Informe a data de referência das recorrências.');return}let existing=old?.recurringPayments||[];if(count)existing=[...existing,...Array.from({length:count},()=>({id:uid(),date:x.recurringDate}))];x.recurringPayments=existing;x.gross=+x.gross;if(!old?.commissionTier){let meet=monthlyMetrics(x.signedDate.slice(0,7)).meet,t=tiers(meet,x.origin),base=x.gross*(1- +db.settings.tax/100);x.meetingsAtSigning=meet;x.commissionTier=t;x.initialRate=t.initial;x.recurringRate=t.recurring;x.netBase=base}else{Object.assign(x,{meetingsAtSigning:old.meetingsAtSigning,commissionTier:old.commissionTier,initialRate:old.initialRate,recurringRate:old.recurringRate,netBase:old.netBase})}upsert('contracts',x,'contract');toast('Contrato salvo')}
function storeGeneric(e,key,kind){e.preventDefault();upsert(key,Object.fromEntries(new FormData(e.target)),kind);toast('Pendência salva')}
function upsert(key,x,k){if(x.id){let i=db[key].findIndex(y=>y.id===x.id);db[key][i]={...db[key][i],...x};delete edit[k]}else{delete x.id;db[key].push({...x,id:uid()})}save();render()}
function download(content,name,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function exportCSV(){let rows=[['tipo','data','identificador','origem_status','valor','detalhes'],...db.launches.map(x=>['lançamento',x.date,x.lead,x.origin,'',x.note]),...db.contracts.map(x=>['contrato',x.signedDate,x.company,`${x.origin} · ${x.status}`,x.gross,x.note]),...db.team.map(x=>['bônus coletivo',x.month,'Contrato do time','',x.gross,x.note]),...db.tasks.map(x=>['pendência',x.due,x.type,x.status,'',x.note])];download('\ufeff'+rows.map(r=>r.map(v=>`"${String(v||'').replaceAll('"','""')}"`).join(';')).join('\n'),'backup-seok-sdr.csv','text/csv;charset=utf-8')}
function importJSON(e){let f=e.target.files[0];if(!f)return;let r=new FileReader;r.onload=()=>{try{let x=JSON.parse(r.result);if(!x.settings||!Array.isArray(x.launches)||!Array.isArray(x.contracts))throw Error();db={...defaults,...x};save();render();toast('Backup importado')}catch{alert('Arquivo JSON de backup inválido.')}};r.readAsText(f)}
function toast(t){setTimeout(()=>{let x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)},0)}
function startIntro(){document.body.classList.add('intro-active');setTimeout(()=>{document.body.classList.add('intro-reveal');$('#seok-splash')?.classList.add('leaving')},4200);setTimeout(()=>{$('#seok-splash')?.remove();document.body.classList.remove('intro-active','intro-reveal')},5000)}
document.addEventListener('click',e=>{if(e.target.closest('[data-tab]'))$('aside')?.classList.remove('open')})
lockExistingContracts()
render()
startIntro()
